def is_valid(s):
    """Return True if every bracket in s is closed by the same kind of bracket, in the right order."""
    ...

solution:
def is_valid(s):
    opener_for = {")": "(", "]": "[", "}": "{"}
    open_brackets = []                              # a stack: the most recent unclosed opener is on top
    for ch in s:
        if ch in opener_for:                        # a closing bracket must match the top of the stack
            if not open_brackets or open_brackets.pop() != opener_for[ch]:
                return False
        else:
            open_brackets.append(ch)
    return not open_brackets                        # anything left over was never closed
